function worldMap(){const cross=DATA.geometry_manifest.crosswalk;const registered=new Set(DATA.entities.filter(e=>e.entity_type!=='aggregate').map(e=>e.entity_id));const project=([lon,lat])=>[(lon+180)*2.5,(90-lat)*2.5];return `<svg class="world-map" viewBox="0 0 900 430" aria-label="Economy map. Select an economy or use the searchable list below." role="group">${DATA.geometry.features.map(f=>{const id=f.properties.entity_id,geo=f.geometry,allowed=registered.has(id)&&cross[id]?.geometry_id===f.properties.geometry_id&&!!economyTarget(id);let shape='';if(geo.type==='Point'){const [x,y]=project(geo.coordinates);shape=`<circle cx="${x}" cy="${y}" r="4"/>`}else{const rings=geo.type==='Polygon'?geo.coordinates:geo.coordinates.flat();shape=`<path d="${rings.map(r=>r.map((p,i)=>(i?'L':'M')+project(p).map(n=>n.toFixed(1)).join(',')).join(' ')+'Z').join(' ')}"/>`}return allowed?`<a href="${esc(url({view:'economies',entity:economyTarget(id)}))}" aria-label="View ${esc(name(economyTarget(id)))}" class="${tracked.some(e=>e.entity_id===id)?'tracked':'group-only'}"><title>${esc(name(id))}${economyTarget(id)!==id?' · part of '+esc(name(economyTarget(id))):''}</title>${shape}</a>`:`<g class="untracked">${shape}</g>`}).join('')}</svg>`}
function economyNote(e){return e.coverage_scope==='aggregate_only'?'Covered as part of '+name(economyTarget(e.entity_id)):e.coverage_scope==='aggregate'?'Group':''}
function economies(){const requested=state.get('entity')||'',id=economyTarget(requested),e=DATA.entities.find(e=>e.entity_id===id),g=DATA.aggregates.find(g=>g.aggregate_id===id);if(requested&&id===null)return heading('Economies','No data for '+esc(name(requested))+' yet.','')+link('← All economies',{entity:null});if(id&&!e&&!g)return heading('Economies','Economy not found','There is no economy with this code.')+link('Back to all economies',{entity:null});if(!id)return heading('Economies','Economies','Select an economy on the map or from the list.')+`<div class="map-panel"><a href="#economy-search">Skip the map and search by name</a>${worldMap()}<p class="meta">Dark: economies with their own data · grey: not covered.</p></div><label class="list-search">Find an economy<input id="economy-search" type="search" placeholder="United Kingdom, GBR, Japan…"></label><div class="economy-list">${economyDirectory().map(e=>`<a data-economy="${esc((e.entity_name+' '+e.entity_id).toLowerCase())}" href="${esc(url({entity:e.entity_id}))}">${esc(e.entity_name)}${economyNote(e)?`<small>${esc(economyNote(e))}</small>`:''}</a>`).join('')}</div>`;const own=DATA.series.filter(s=>owner(s)===id&&(numeric(s).length||waiting(s))),rates=rateSlots(id),shown=new Set(indicators.flatMap(f=>chosen(id,f).list.map(s=>s.series_id))),other=own.filter(s=>!shown.has(s.series_id)).sort((a,b)=>title(a).localeCompare(title(b))),pubs=publications('0000-01-01','9999-12-31').filter(p=>p.affected_entities.includes(id));return (requested!==id?`<p class="notice">${esc(name(requested))} has no profile of its own. It is covered as part of ${esc(name(id))}.</p>`:'')+heading('Economies / '+esc(name(id)),esc(name(id)),'')+`<div class="inline-actions">${link('← All economies',{entity:null})}${link('All '+own.length+' series',{view:'series',q:'economy:'+id,series:null,compare:null})}${g?'':link('Publications',{view:'publications',q:'economy:'+id,from:pubs.at(-1)?.release_date||null,to:pubs[0]?.release_date||null,day:null,status:null,event:null})}</div>${memberships(id).length?`<section class="economy-part-of"><h2>Part of</h2><div class="inline-links">${memberships(id).map(g=>link(g.name,{entity:g.aggregate_id})).join('')}</div></section>`:''}${g?`<section class="economy-group-section"><h2>About this group</h2><p>${esc(g.rationale)}</p><p class="meta">${esc(g.composition_basis)} Membership as of ${esc(publicationDate(g.composition_as_of))}.</p><h2>Members (${g.member_ids.length})</h2><div class="inline-links">${g.member_ids.map(m=>{const t=economyTarget(m);return !t||t===id?`<span>${esc(name(m))}</span>`:link(name(m),{entity:t})}).join('')}</div>${link('Compare members →',{view:'indicators',group:g.aggregate_id})}</section>`:''}${entityCards(id)}<div class="section-heading"><h2>Interest rates</h2></div><div class="kpi-grid">${rates.map(([f])=>slotCard(id,f)).join('')}</div>${other.length?`<details class="other-indicators"><summary>Other indicators · ${other.length}</summary><div class="kpi-grid">${other.map(s=>card(s)).join('')}</div></details>`:''}${g?'':`<h2 class="economy-publications-heading">Recent publications</h2>${pubs.slice(0,8).map(pubRow).join('')||'<p>No publications for this economy are listed yet.</p>'}`}`}
function seriesPage(){const q=state.get('q')||'',id=state.get('series'),a=byId.get(id),b=byId.get(state.get('compare')),matches=DATA.series.filter(s=>listed(s)&&queryMatch(q,{economy:owner(s)+' '+name(owner(s)),economy_id:owner(s),publisher:provider(s),indicator:s.indicator+' '+title(s),code:s.provider_code||'',id:s.series_id}));const page=Math.max(0,Math.min(Number(state.get('page'))||0,Math.ceil(matches.length/30)-1));return heading('Series','Series','Search all data series, read their definitions and compare two series.')+searchForm(q)+`<div class="series-layout"><section class="catalogue"><h2>${matches.length} series</h2><p class="meta">${matches.length?`${page*30+1}–${Math.min((page+1)*30,matches.length)} of ${matches.length}`:'No matches'}</p>${matches.slice(page*30,(page+1)*30).map(s=>`<article><p class="eyebrow">${economyLink(s,name(owner(s)))}</p><h3>${indicatorLink(s)}${info(s)}</h3><p class="meta">${esc(provider(s))} · ${esc(cap(s.frequency))} · ${esc(unit(s))}</p><div class="inline-actions">${link(a?'Replace':'View',{series:s.series_id})}${a&&a.series_id!==s.series_id?link('Compare',{compare:s.series_id}):''}<button data-add="${esc(s.series_id)}">+ Add to notebook</button></div></article>`).join('')||'<p>No series found. Try fewer terms.</p>'}<div class="inline-actions">${page>0?link('← Previous results',{page:page-1}):''}${(page+1)*30<matches.length?link('Next results →',{page:page+1}):''}</div></section><section class="analysis">${a?`<label class="scale-toggle first-toggle"><input type="checkbox" id="first-estimates" ${state.get('vintage')==='first'?'checked':''}>Show first estimates instead of latest values</label>${state.get('vintage')==='first'?'<p class="meta">First estimates: each period as first published, or as first held where our record starts later.</p>':''}`:''}${state.get('compare')&&!b?'<p class="notice">The comparison series could not be found. Choose another.</p>':''}${seriesAnalysis(a,b,id)}</section></div>`}
function compareNotice(a,b){const same=a.indicator===b.indicator&&a.unit===b.unit&&a.frequency===b.frequency&&a.adjustment===b.adjustment;return `<p class="notice">${same?'Same indicator, frequency and unit. Check definitions and geographic coverage before drawing conclusions.':'These series measure different things or use different definitions, so no difference is calculated.'}</p>`}
// How a card names a diverged companion: the publisher, or, when both companions come from the same publisher, which of its routes.
function companionName(other,self){const p=shortProvider(provider(other));if(provider(other)!==provider(self))return p;return other.source_kind==='extracted'?p+(p.endsWith('s')?"' release figures":"'s release figures"):p+(p.endsWith('s')?"' data table":"'s data table")}
function pairScale(a,b){const ends=[a,b].map(s=>latest(s)).filter(Boolean).map(r=>date(r.period));if(!ends.length)return null;const end=Math.max(...ends),start=end-3*365.25*864e5;const vals=[a,b].flatMap(s=>numeric(s).filter(r=>date(r.period)>=start&&date(r.period)<=end).map(r=>r.value));return {start,end,lo:Math.min(0,...vals),hi:Math.max(0,...vals)}}
function scaleToggle(a,b,same,attrs){return unit(a)===unit(b)?`<label class="scale-toggle"><input type="checkbox" ${attrs} ${same?'checked':''}>Same scale and period on both charts</label>`:''}
function compareMeta(a,b,same=false){const common=numeric(a).filter(r=>numeric(b).some(x=>x.period===r.period)).at(-1),other=common&&numeric(b).find(r=>r.period===common.period);return `<p class="meta">${same?'Both charts share one scale and the same three-year period.':'Each chart has its own scale and shows its own latest period.'} ${common?`Latest period in common: ${esc(common.period)} · ${fmtU(common.value,a)}${unit(a)&&unit(a)[0]!=='%'?' ':''}${esc(unit(a))} compared with ${fmtU(other.value,b)}${unit(b)&&unit(b)[0]!=='%'?' ':''}${esc(unit(b))}.`:'No period in common.'}</p>`}
function comparison(a,b){const same=state.get('scale')==='same'&&unit(a)===unit(b),shared=same?pairScale(a,b):null;return compareNotice(a,b)+scaleToggle(a,b,same,'id="scale-same"')+`<div class="comparison-pair">${view==='series'?seriesSelectionCard(a,'series','Selected series',shared):card(a,'',name(owner(a)),shared)}${view==='series'?seriesSelectionCard(b,'compare','Comparison',shared):card(b,'',name(owner(b)),shared)}</div>`+compareMeta(a,b,same)}
function notebookPage(){return heading('Notebook','Notebook','Save series, compare them and add your own notes. Stored in this browser; copy the link to share or keep it.')+`<p class="meta">Data as of ${esc(publicationDate(asof||DATA.generated_at.slice(0,10)))}</p>${hasNotebookBackup()?'<p class="notice" id="shared-notebook-notice">You opened a shared notebook. <a href="#restore-notebook" id="restore-notebook">Restore my own notebook</a></p>':''}<div class="inline-actions">${link('Find series to add',{view:'series'})}</div><label class="notebook-share" for="notebook-url">Link to this notebook</label><div class="notebook-share-row"><input id="notebook-url" readonly aria-label="Notebook URL" placeholder="Preparing link…"><button id="copy-notebook-url" type="button">Copy link</button></div><p id="notebook-url-status" class="meta" role="status">Copy this link to keep or share your notebook, including notes.</p><div class="notebook-blocks">${notebook.length?notebook.map((n,i)=>notebookBlock(n,i)).join(''):'<div class="empty-panel"><h2>Your notebook is empty</h2><p>Choose “Add to notebook” on any chart or series.</p></div>'}</div>`}
function compareEmpty(i){return `<div class="compare-empty"><button type="button" class="compare-add" data-compare-add="${i}" aria-label="Add a comparison series">+</button><p>Add a comparison</p></div>`}
function notebookBlock(n,i){const s=byId.get(n.series),c=n.mode==='series'?byId.get(n.compare):null;if(!s)return `<article class="note-block missing-block"><h2>Series no longer available</h2><p class="meta">${esc(n.series)}</p>${n.note?`<blockquote>${esc(n.note)}</blockquote>`:''}<button data-remove="${i}">Remove</button></article>`;const same=!!c&&n.scale==='same'&&unit(s)===unit(c),shared=same?pairScale(s,c):null;return `<article class="note-block"><div class="section-heading"><div><p class="eyebrow">Item ${i+1} · ${esc(name(owner(s)))}</p><h2>${esc(title(s))}</h2></div><div class="inline-actions"><button data-up="${i}" ${i===0?'disabled':''}>Move up</button><button data-remove="${i}">Remove</button></div></div>${c?compareNotice(s,c)+scaleToggle(s,c,same,`data-scale="${i}"`):''}<div class="note-pair"><div class="note-main">${card(s,'',null,shared,null,evidence(s))}</div><div class="note-compare" data-compare-slot="${i}">${c?`<div class="compare-card">${card(c,'',null,shared,null,evidence(c))}<button type="button" class="compare-remove" data-compare-remove="${i}" aria-label="Remove comparison">×</button></div>`:compareEmpty(i)}</div></div>${c?compareMeta(s,c,same):''}<label class="note-label">Your notes<textarea data-note="${i}" rows="3" placeholder="Add your notes…">${esc(n.note||'')}</textarea></label></article>`}
function publisherTerms(publisher){
  if(publisher==='Macroeconomic Outlook')return '';
  const row=(DATA.source_terms||[]).find(r=>r.publisher===publisher||(r.aliases||[]).includes(publisher));
  if(!row)return '<div class="source-terms"><p class="meta">Licence: not recorded</p></div>';
  const reuse={open:'Licence: open reuse',open_with_attribution:'Licence: reuse with attribution',non_commercial:'Licence: non-commercial reuse only',no_redistribution:'Licence: no redistribution',unclear:row.terms_url?'Licence: terms unclear':'Licence: terms not found'};
  const statement=row.decision==='owner_review'?'Reuse terms not yet confirmed':row.decision==='link_only'?'We link to this publisher\'s releases but do not reproduce its figures.':row.statement;
  return `<div class="source-terms"><p class="meta">${esc(reuse[row.reuse]||reuse.unclear)}</p>${statement?`<p>${esc(statement)}</p>`:''}${row.terms_url?`<p>${sourceLink(row.terms_url,'Publisher terms of use')}</p>`:''}</div>`;
}
function sourcesPage(){const q=state.get('q')||'',sources=DATA.calendar.sources.filter(s=>queryMatch(q,{publisher:s.publisher,economy:s.entity_id+' '+name(s.entity_id),economy_id:s.entity_id,indicator:s.publication_scope}));return heading('Sources and coverage','Sources and coverage','The institutions behind the data on this site, and the licences under which they publish it, where available.')+searchForm(q)+`<p class="result-count">${sources.length} sources · ${DATA.series.length} series · ${tracked.length} economies</p><div class="source-grid">${sources.map(s=>`<article><p class="eyebrow">${esc(name(s.entity_id))}</p><h3>${esc(s.publisher)}</h3><p>${esc(s.publication_scope)}</p>${publisherTerms(s.publisher)}${s.verification_status==='blocked'?'<p class="notice">Not collected automatically. This publisher\'s terms forbid automated access, so its release dates are not listed here.</p>':''}<div><p>Last checked ${esc(publicationDate(s.checked_on))}</p>${sourceLink(s.calendar_url,'Release calendar')}</div></article>`).join('')}</div>`}
// Copies text to the clipboard, falling back to selecting it in `field` (or a hidden field) and the browser's copy command.
async function copyText(text,field=null){try{await navigator.clipboard.writeText(text);return 'copied'}catch{}const own=!field;if(own){field=document.createElement('textarea');field.value=text;field.setAttribute('readonly','');field.style.position='fixed';field.style.opacity='0';document.body.append(field)}field.focus();field.select();let ok=false;try{ok=document.execCommand('copy')}catch{}if(own)field.remove();return ok?'copied':'selected'}
function toast(html){clearTimeout(toastTimer);$('#toast').innerHTML=html;toastTimer=setTimeout(()=>$('#toast').innerHTML='',5000)}
function showNotice(id,html){if($('#'+id))return $('#'+id);const p=document.createElement('p');p.className='notice page-notice';p.id=id;p.innerHTML=`<span>${html}</span><button type="button" aria-label="Dismiss notice">Dismiss</button>`;p.querySelector('button').onclick=()=>p.remove();$('#page-notices').append(p);return p}
function openCompareSearch(i){const slot=$(`[data-compare-slot="${i}"]`);if(!slot)return;slot.innerHTML=`<div class="compare-search"><label>Compare with<input type="search" data-compare-search="${i}" placeholder="Search series to compare" autocomplete="off"></label><div class="compare-results" role="list"></div></div>`;const input=slot.querySelector('input'),out=slot.querySelector('.compare-results');input.oninput=()=>{const q=input.value.trim();out.innerHTML=q?DATA.series.filter(s=>s.series_id!==notebook[i].series&&listed(s)&&queryMatch(q,{economy:owner(s)+' '+name(owner(s)),economy_id:owner(s),publisher:provider(s),indicator:title(s)+' '+s.indicator})).slice(0,20).map(s=>`<button type="button" role="listitem" data-series="${esc(s.series_id)}">${esc(name(owner(s))+' · '+title(s)+' · '+sourceLine(s))}</button>`).join(''):'';out.querySelectorAll('button').forEach(b=>b.onclick=()=>{notebook[i].compare=b.dataset.series;notebook[i].mode='series';saveNotes();render()})};input.focus()}
function saveNotes(){updateNotebookURL();try{localStorage.setItem('macro-design-notebook-v2',JSON.stringify(notebook))}catch{$('#toast').textContent='Your browser is blocking storage. Copy your notebook link before leaving.'}}
