function closeInfo(except){$$('.info-pop:not([hidden])').forEach(p=>{if(p!==except){p.hidden=true;document.querySelector(`[aria-controls="${p.id}"]`)?.setAttribute('aria-expanded','false')}})}
function infoClick(e){const b=e.target.closest?.('.info-btn');if(b){const p=document.getElementById(b.getAttribute('aria-controls'));closeInfo(p);if(p){p.hidden=!p.hidden;b.setAttribute('aria-expanded',String(!p.hidden))}return}if(!e.target.closest?.('.info-pop'))closeInfo()}
function sparkPoints(svg){return svg._pts??=JSON.parse(svg.dataset.points||'[]')}
function sparkShow(svg,i){const pts=sparkPoints(svg);if(!pts.length)return;i=Math.max(0,Math.min(pts.length-1,i));svg._idx=i;const [x,y,p,v]=pts[i],ty=y-12<20?y+26:y-12;sparkClear();const g=document.createElementNS('http://www.w3.org/2000/svg','g');g.setAttribute('class','spark-hover');g.innerHTML=`<path d="M${x} 25V155" stroke="currentColor" opacity=".3"/><circle cx="${x}" cy="${y}" r="5"/><rect rx="3"/><text x="${x+10}" y="${ty}">${esc(p+': '+v)}</text>`;svg.append(g);const tx=g.querySelector('text');if(x+10+tx.getBBox().width>595){tx.setAttribute('x',x-10);tx.setAttribute('text-anchor','end')}const b=tx.getBBox(),r=g.querySelector('rect');r.setAttribute('x',b.x-5);r.setAttribute('y',b.y-3);r.setAttribute('width',b.width+10);r.setAttribute('height',b.height+6)}
function sparkClear(){$$('.spark-hover').forEach(g=>g.remove())}
function sparkPointer(e){const svg=e.target.closest?.('svg.spark'),ctm=svg?.getScreenCTM();if(!svg&&e.type==='pointerdown')sparkClear();if(!ctm)return;const px=(e.clientX-ctm.e)/ctm.a,pts=sparkPoints(svg);let best=0;pts.forEach((p,i)=>{if(Math.abs(p[0]-px)<Math.abs(pts[best][0]-px))best=i});sparkShow(svg,best)}
function sparkKey(e){if(e.key==='Escape')closeInfo();const svg=e.target.closest?.('svg.spark');if(svg&&(e.key==='ArrowLeft'||e.key==='ArrowRight')){e.preventDefault();sparkShow(svg,(svg._idx??sparkPoints(svg).length)+(e.key==='ArrowLeft'?-1:1))}}
document.addEventListener('click',infoClick);document.addEventListener('pointermove',sparkPointer);document.addEventListener('pointerdown',sparkPointer);document.addEventListener('keydown',sparkKey);window.addEventListener('scroll',()=>{if(document.querySelector('.spark-hover'))sparkClear()},{passive:true});document.addEventListener('pointerout',e=>{if(e.pointerType==='touch')return;const svg=e.target.closest?.('svg.spark');if(svg&&!svg.contains(e.relatedTarget))svg.querySelector('.spark-hover')?.remove()});document.addEventListener('focusout',e=>{if(e.target.matches?.('svg.spark'))e.target.querySelector('.spark-hover')?.remove()});
document.addEventListener('toggle',e=>{const d=e.target;if(d.matches?.('details.evidence')&&d.open){const el=d.querySelector('[data-revisions]');if(el)loadRevisions(el)}},true);
function routeClick(e){const a=e.target.closest('a');if(a&&a.getAttribute('href')?.startsWith('?')&&!e.ctrlKey&&!e.metaKey&&!e.shiftKey&&!e.button){e.preventDefault();go(a.getAttribute('href'))}}
function navUrl(v){const p=new URLSearchParams({view:v}),t=encodeT();if(t)p.set('t',t);if(asof)p.set('asof',asof);return '?'+p.toString()}
function navLink(v,text,cls=''){return `<a class="${cls}" href="${esc(navUrl(v))}">${esc(text)}</a>`}
function economyTitle(id){return DATA.entities.some(e=>e.entity_id===id)||DATA.aggregates.some(g=>g.aggregate_id===id)?name(economyTarget(id)||id):'Economy not found'}
function render(){readVintageView();applyAppearance();$('header .brand').href=navUrl('home');$('footer>a').href=navUrl('sources');$('#license-link').href=navUrl('license');$('footer').firstChild.textContent='Updated on '+publicationDate(DATA.generated_at.slice(0,10))+' ';$('#nav').innerHTML=[['home','Overview'],['publications','Publications'],['indicators','Indicators'],['economies','Economies'],['series','Series'],['notebook','Notebook']].map(([v,t])=>navLink(v,t,view===v?'active':'')).join('')+'<button class="appearance-toggle" popovertarget="appearance-panel" title="Choose appearance"><span aria-hidden="true">◐</span> Display</button>'+(ASOF_TOOLS?'<button class="copy-page-link" id="copy-page-link" type="button">Copy link to this page</button>':'');contextBar();asofNotice();staleNotice();const pages={home,publications:news,indicators:indicatorPage,economies,series:seriesPage,notebook:notebookPage,sources:sourcesPage,license:licensePage},page=Object.hasOwn(pages,view)?view:'missing';const entity=view==='economies'&&state.get('entity');document.title=page==='home'?'Macroeconomic Outlook':(entity?economyTitle(entity):PAGE_TITLES[page])+' · Macroeconomic Outlook';$('footer>a').classList.toggle('active',view==='sources');$('#license-link').classList.toggle('active',view==='license');$('#main').innerHTML=(pages[page]||notFound)();bind()}
// The context bar is built once, so typing a date is never interrupted by the page being drawn again; a change applies
// after a short pause, as a date input reports each edited segment of the date as a change.
let asofTimer;function contextBar(){const ctx=$('#context');let input=$('#asof-input');if(!ctx.querySelector('.context-tools')){ctx.innerHTML=`<span>Updated on ${esc(DATA.generated_at.slice(0,10).split('-').reverse().join('.'))}</span><span class="context-tools">${ASOF_TOOLS?`<label class="asof-control"><span>As of</span><input type="date" id="asof-input" min="${esc(EARLIEST_PUBLISHED)}" max="${esc(DATA_DATE)}"></label>`:''}${navLink('sources','Sources and coverage')}</span>`;input=$('#asof-input');input?.addEventListener('change',()=>{clearTimeout(asofTimer);asofTimer=setTimeout(()=>{const v=input.value;if(v&&!isDay(v)||v===asof)return;asofDismissed='';vintageFailed.clear();history.pushState(null,'',url({asof:v||null}));state=new URLSearchParams(location.search);render()},400)})}if(input&&document.activeElement!==input)input.value=asof;ctx.querySelector('.context-tools>a').href=navUrl('sources')}
function asofNotice(){const n=$('#asof-notice');if(!asof||asofDismissed===asof){n?.remove();return}const p=n||showNotice('asof-notice','');p.querySelector('span').innerHTML=`Data as published on ${esc(publicationDate(asof))}. Revisions and releases since then are not shown; our record begins on ${esc(publicationDate(EARLIEST_PUBLISHED))}. ${link('Show the latest data',{asof:null})}.`;if(!n){$('#page-notices').prepend(p);p.querySelector('button').onclick=()=>{asofDismissed=asof;p.remove()}}}
// The stale-link notice: a link that already carries asof is shown as of its date, so the notice only says the link is old;
// one without asof is offered the data as of its snapshot's date.
function staleNotice(){const n=$('#stale-link-notice'),v=staleSnapshot();if(!v||staleDismissed){n?.remove();return}const html=asof?'This link was made before the latest update.':`This link was made before the latest update. You are seeing the data as of ${esc(publicationDate(DATA.generated_at.slice(0,10)))}.${ASOF_TOOLS&&isDay(v)&&v<=DATA_DATE?' '+link(`Show the data as it was on ${publicationDate(v)}.`,{asof:v},'stale-asof'):''}`;if(n){if(n.dataset.html!==html){n.dataset.html=html;n.querySelector('span').innerHTML=html}return}const p=showNotice('stale-link-notice',html);p.dataset.html=html;p.querySelector('button').onclick=()=>{staleDismissed=true;p.remove()}}
const PAGE_TITLES={publications:'Publications',indicators:'Indicators',economies:'Economies',series:'Series',notebook:'Notebook',sources:'Sources and coverage',license:'Licence',missing:'Page not found'};
function notFound(){return heading('Page not found','Page not found','This page does not exist.')+link('Go to the overview',{view:'home'})}
document.addEventListener('click',routeClick);document.querySelectorAll('[data-setting]').forEach(button=>button.addEventListener('click',()=>{const k=button.dataset.setting,v=button.dataset.value;if(k==='typeface')typeface=v;else if(k==='colours')colours=v;else mode=mode===v?'':v;prefs={typeface,colours,mode};try{localStorage.setItem('macro-appearance',JSON.stringify(prefs))}catch{}history.replaceState(null,'',url()+location.hash);state=new URLSearchParams(location.search);render();button.focus()}));window.onpopstate=()=>{state=new URLSearchParams(location.search);view=state.get('view')||'home';history.replaceState(null,'',url()+location.hash);state=new URLSearchParams(location.search);render()};try{matchMedia('(prefers-color-scheme: dark)').addEventListener('change',applyAppearance)}catch{}
// An old link's snapshot stays in the address while its page is shown, for the stale-link notice; a current one goes, as do old appearance settings.
if(['snapshot','theme','palette','appearance'].some(k=>state.has(k))){const p=new URLSearchParams(url().slice(1)),v=staleSnapshot();if(v)p.set('snapshot',v);history.replaceState(null,'','?'+p+location.hash);state=new URLSearchParams(location.search)}restoreNotebookURL().then(render);



function seriesSelectionCard(s,key,label,shared=null){return `<section class="series-selection"><div class="section-heading"><h2>${label}</h2><button data-remove-series="${key}" aria-label="Remove ${label.toLowerCase()}">Remove</button></div>${card(s,'',name(owner(s)),shared,null,evidence(s))}</section>`}
function seriesAnalysis(a,b,id){const selected=a?seriesSelectionCard(a,'series','Selected series'):`<section class="empty-panel"><h2>Selected Series</h2><p>${id?'This series could not be found.':'Choose a series from the list.'}</p></section>`;return (a&&b?comparison(a,b):`<div class="${b?'comparison-pair':''}">${selected}${b?seriesSelectionCard(b,'compare','Comparison'):''}</div>`)}

function licensePage(){return heading('Licence','Licence','Macroeconomic Outlook by Josh Levent.')+`<section class="license-copy"><h2>Non-commercial use</h2><p>Unless otherwise stated, the original content and design of this public site by Josh Levent are licensed under the <a rel="license" href="https://creativecommons.org/licenses/by-nc/4.0/">Creative Commons Attribution-NonCommercial 4.0 International licence (CC BY-NC 4.0)</a>.</p><p>You may share and adapt this material for non-commercial purposes under that licence. Credit Josh Levent and Macroeconomic Outlook, link to the original material and the licence, and indicate any changes.</p><h2>Commercial licensing</h2><p>For a commercial licence, email <a href="mailto:josh@joshlevent.com">josh@joshlevent.com</a>.</p><h2>Third-party material and data</h2><p>Statistics, publications and other material credited to third parties remain subject to their own licences and terms. This site's licence does not replace those terms or grant rights to third-party material.</p><p>${link('Sources and coverage',{view:'sources'})} identifies the institutions behind the data and the licences under which they are published, where available.</p><p>Map boundaries: Natural Earth (public domain), simplified.</p></section>`}
